--
-- GR-02 / REQ-004 — catalog section repair.
--
-- The preserved catalog tagged no exercise skill_power, carries or
-- stability_balance, and no exercise that can be done without an implement was
-- primary_lift. The section-mapping ledger records, row by row with evidence,
-- which exercises belong there. This migration applies those 28 rows to
-- public.exercise_definitions and nothing else. supabase/seed/ is generated from
-- the same rows, so a database seeded after this migration and one migrated
-- after its seed hold the same catalog.
--
-- Additive. Each line below names one exercise, the sections it gains and
-- whether it becomes eligible as a primary lift. A section is appended only
-- where the exercise does not already carry it; can_be_primary is only ever
-- raised. No tag is taken away, no row is inserted or removed, and an
-- exercise the ledger does not name is not touched.
--
-- Idempotent. The WHERE clause selects a row only while something is still
-- missing from it, so a second apply updates zero rows and the updated_at
-- trigger does not fire. On a project with no catalog rows yet it updates
-- nothing, and the seed supplies the same values.
--
-- Rollback: docs/backend/catalog-section-repair-rollback.md.

update public.exercise_definitions as d
set
  sections = d.sections || array(
    select added.tag
    from unnest(r.add_sections) with ordinality as added(tag, ord)
    where added.tag <> all (d.sections)
    order by added.ord
  ),
  can_be_primary = d.can_be_primary or r.make_primary
from (values
  ('box-jumps', array['skill_power']::public.section_type[], false),
  ('squat-jumps', array['skill_power']::public.section_type[], false),
  ('power-clean', array['skill_power']::public.section_type[], false),
  ('hang-clean', array['skill_power']::public.section_type[], false),
  ('squat-clean', array['skill_power']::public.section_type[], false),
  ('hang-snatch', array['skill_power']::public.section_type[], false),
  ('snatch', array['skill_power']::public.section_type[], false),
  ('push-jerk', array['skill_power']::public.section_type[], false),
  ('split-jerk', array['skill_power']::public.section_type[], false),
  ('clean-pull', array['skill_power']::public.section_type[], false),
  ('muscle-clean', array['skill_power']::public.section_type[], false),
  ('high-pulls', array['skill_power']::public.section_type[], false),
  ('farmers-carry', array['carries']::public.section_type[], false),
  ('suitcase-carry', array['carries']::public.section_type[], false),
  ('overhead-carry', array['carries']::public.section_type[], false),
  ('rack-carry', array['carries']::public.section_type[], false),
  ('single-leg-rdl', array['stability_balance', 'primary_lift']::public.section_type[], true),
  ('single-leg-glute-bridge', array['stability_balance']::public.section_type[], false),
  ('bulgarian-split-squat', array['stability_balance', 'primary_lift']::public.section_type[], true),
  ('split-squat', array['stability_balance', 'primary_lift']::public.section_type[], true),
  ('reverse-lunges', array['stability_balance', 'primary_lift']::public.section_type[], true),
  ('goblet-reverse-lunges', array['stability_balance']::public.section_type[], false),
  ('walking-lunges', array['stability_balance', 'primary_lift']::public.section_type[], true),
  ('walking-lunges-oh', array['stability_balance']::public.section_type[], false),
  ('lateral-lunges', array['stability_balance', 'primary_lift']::public.section_type[], true),
  ('push-ups', array['primary_lift']::public.section_type[], true),
  ('decline-push-ups', array['primary_lift']::public.section_type[], true),
  ('box-step-ups', array['stability_balance']::public.section_type[], false)
) as r(id, add_sections, make_primary)
where d.id = r.id
  and (
    not (d.sections @> r.add_sections)
    or (r.make_primary and not d.can_be_primary)
  );
